export const BODY: string = "\n<p>شعار SVG يمكن تكبيره إلى أي حجم دون أن يضبب أبدًا، لكن نصف الأماكن التي تريد استخدامه فيها لا تقبل SVG.</p>\n<p>تحويل SVG إلى PNG، ما يسمى التنقيط، يحوّل الأشكال المتجهة إلى شبكة بكسلات ثابتة. اختر المقياس الصحيح وستبدو النتيجة مثالية.</p>\n<p>يشرح هذا الدليل كيف يعمل التنقيط، وما المقياس الذي تختاره، والأخطاء التي تصطاد المبتدئين.</p>\n<h2 id=\"what-is-svg\">ما ملف SVG؟</h2>\n<p>ما ملف SVG؟ صيغة صور متجهة تصف الأشكال بالمعادلات لا بالبكسلات. يمكن تكبيرها إلى أي حجم دون فقدان الحدة.</p>\n<p>SVG مناسب للشعارات والأيقونات والرسوم. لكن كثير من الأنظمة والتطبيقات لا تقبل SVG وتحتاج إلى PNG.</p>\n<h2 id=\"what-is-rasterizing\">ماذا يعني التنقيط؟</h2>\n<p>ماذا يعني التنقيط؟ تحويل الأشكال المتجهة إلى شبكة بكسلات ثابتة. كل شكل يصبح بكسلات بأبعاد محددة تختارها.</p>\n<p>بعد التنقيط، لا يمكن تكبير الصورة دون فقدان الحدة. لذلك اختر المقياس الصحيح من البداية.</p>\n<h2 id=\"choosing-scale\">اختيار المقياس الصحيح</h2>\n<p>اختيار المقياس الصحيح: المقياس يحدد حجم PNG الناتج. مقياس 1x يعطي الحجم الأصلي، و2x يضاعفه، و4x يضاعفه أربع مرات.</p>\n<p>لأيقونة 24 بكسل، استخدم 4x أو 8x. للشعارات الكبيرة، 2x كافٍ غالبًا. المقياس الأكبر يعني ملفًا أكبر.</p>\n<h2 id=\"transparency-preserved\">الشفافية تُحفظ</h2>\n<p>الشفافية تُحفظ: SVG وPNG يدعمان الشفافية، لذلك تنتقل سليمة من SVG إلى PNG دون أي تغيير.</p>\n<p>تحقق من الشفافية بعد التحويل بفتح الصورة على خلفية ملونة. إذا ظهرت الخلفية من خلال الصورة، فالشفافية سليمة.</p>\n<h2 id=\"fonts-and-text\">الخطوط والنص داخل SVG</h2>\n<p>الخطوط والنص داخل SVG: النص في SVG يعتمد على الخطوط المتاحة. إذا لم يكن الخط متاحًا أثناء التحويل، فسيُستبدل بخط افتراضي.</p>\n<p>لضمان ظهور النص بشكل صحيح، حوّل النص إلى مسارات قبل التحويل، أو تأكد من أن الخط متاح في المتصفح.</p>\n<h2 id=\"linked-images\">الصور المرتبطة والملفات الخارجية</h2>\n<p>الصور المرتبطة والملفات الخارجية: إذا كان SVG يشير إلى صورة خارجية، فلن تظهر في PNG المحوّل لأن الملف الخارجي لا يُرفع.</p>\n<p>أدرج الصور داخل SVG قبل التحويل. الصور المضمّنة تنتقل مع الملف وتظهر في النتيجة.</p>\n<h2 id=\"gradients-and-opacity\">التدرجات والشفافية والتأثيرات</h2>\n<p>التدرجات والشفافية والتأثيرات: معظم التدرجات والتأثيرات تنتقل سليمة إلى PNG. لكن بعض التأثيرات المعقدة قد تظهر بشكل مختلف.</p>\n<p>راجع النتيجة بعد التحويل وتأكد من أن التدرجات تبدو صحيحة. إذا تغير مظهرها، فبسّط التأثيرات في SVG الأصلي.</p>\n<h2 id=\"batch-converting-icons\">تحويل حزمة أيقونات بالجملة</h2>\n<p>لتحويل حزمة أيقونات بالجملة، ارفع كل ملفات SVG وحوّلها بمقياس موحد. الأداة تحوّل الدفعة كاملة وتنزّلها كملف ZIP.</p>\n<p>استخدم المقياس نفسه لكل الأيقونات. الاتساق يجعل الحزمة تبدو احترافية وموحدة.</p>\n<h2 id=\"when-to-use-png-instead\">متى تستخدم PNG بدل SVG؟</h2>\n<p>متى تستخدم PNG بدل SVG؟ عندما ترسل الصورة إلى نظام لا يدعم SVG، أو تطبعها، أو تستخدمها في تطبيق قديم.</p>\n<p>استخدم PNG أيضًا عندما تحتاج إلى حجم ثابت لا يتغير. SVG مرن، وPNG ثابت وقابل للتنبؤ.</p>\n<h2 id=\"colour-accuracy\">هل التحويل يغيّر الألوان؟</h2>\n<p>هل التحويل يغيّر الألوان؟ عادة لا. الألوان في SVG تُحفظ كما هي في PNG، لكن ملفات الألوان قد تسبب اختلافًا طفيفًا.</p>\n<p>إذا تغيرت الألوان بعد التحويل، فتحقق من ملف الألوان في SVG الأصلي. معظم الحالات لا تتأثر.</p>\n<h2 id=\"file-sizes\">أحجام الملفات بعد التحويل</h2>\n<p>أحجام الملفات بعد التحويل: PNG الناتج أكبر من SVG عادة، خاصة عند المقاييس الكبيرة. SVG ملف نصي صغير، وPNG شبكة بكسلات.</p>\n<p>المقياس الأكبر يعني ملفًا أكبر. اختر أصغر مقياس يلبي احتياجك لتوفير المساحة.</p>\n<h2 id=\"common-problems\">مشاكل شائعة وحلولها</h2>\n<p>مشاكل شائعة وحلولها: صورة مفقودة تعني ملفًا خارجيًا غير مضمّن، ونص غريب يعني خطًا غير متاح، وضبابية تعني مقياسًا صغيرًا جدًا.</p>\n<p>أصلح السبب في SVG الأصلي ثم أعد التحويل. التحويل نفسه نادرًا ما يكون المشكلة.</p>\n<h2 id=\"svg-logos-social-media\">شعارات SVG لوسائل التواصل</h2>\n<p>شعارات SVG لوسائل التواصل: حوّلها إلى PNG قبل الرفع. معظم المنصات لا تقبل SVG، وPNG يعمل في كل مكان.</p>\n<p>استخدم مقياسًا كبيرًا للشعارات الاجتماعية. الشعار يظهر بأحجام مختلفة، والمقياس الكبير يضمن حدته.</p>\n<h2 id=\"svg-icons-apps\">أيقونات SVG للتطبيقات</h2>\n<p>أيقونات SVG للتطبيقات: حوّلها إلى PNG بالأحجام التي يحتاجها تطبيقك. كل نظام يحتاج إلى أحجام أيقونات محددة.</p>\n<p>حوّل كل حجم على حدة بمقياس مناسب. الأيقونات بأحجام متعددة تضمن ظهورها بشكل صحيح في كل مكان.</p>\n<h2 id=\"svg-for-print-materials\">SVG لمواد مطبوعة</h2>\n<p>SVG لمواد مطبوعة: حوّلها إلى PNG بمقياس كبير للطباعة. الطباعة تحتاج دقة عالية، لذلك استخدم 4x أو أكثر.</p>\n<p>اطبع من ملف PNG المحوّل. الطباعة تحتاج دقة كاملة، والمقياس الكبير يضمن حدة الطباعة.</p>\n<h2 id=\"svg-for-email-signatures\">SVG لتوقيعات البريد الإلكتروني</h2>\n<p>SVG لتوقيعات البريد الإلكتروني: حوّل الشعار إلى PNG صغير قبل إدراجه في التوقيع. التوقيعات تحتاج إلى صور صغيرة سريعة.</p>\n<p>استخدم مقياسًا صغيرًا للتوقيعات. الصورة الصغيرة تحمل أسرع وتبدو نظيفة في البريد.</p>\n<h2 id=\"svg-for-favicons\">SVG للأيقونات المفضلة</h2>\n<p>SVG للأيقونات المفضلة: حوّلها إلى PNG بالأحجام التي يحتاجها المتصفح. الأيقونة المفضلة تظهر في علامات التبويب والإشارات.</p>\n<p>وللخطوات العملية، استخدم <a href=\"/ar/tahwil-svg-ila-png/\">محول SVG إلى PNG</a>، واقرأ <a href=\"/ar/blog/kayfiyya-tahwil-svg-ila-png/\">كيفية تحويل SVG إلى PNG</a> و<a href=\"/ar/blog/svg-vs-png-mutajjih-wa-nuqti/\">SVG مقابل PNG: متجه ونقطي</a>، أو جرّب <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> لصيغ أخرى.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما المقياس الذي أختاره لتحويل أيقونة 24 بكسل إلى PNG حاد؟","answer":"لأيقونة 24 بكسل، استخدم مقياس 4x أو 8x للحصول على PNG حاد. المقياس 1x يعطي 24 بكسل فقط، وهو صغير جدًا لمعظم الاستخدامات."},{"question":"هل تحويل SVG إلى PNG يحافظ على الخلفية الشفافة؟","answer":"نعم، التحويل يحافظ على الخلفية الشفافة. SVG وPNG يدعمان الشفافية، لذلك تنتقل سليمة."},{"question":"لماذا تختفي صورة مرتبطة في ملف PNG المحوّل؟","answer":"لأن الصورة المرتبطة ملف خارجي لا يُرفع مع SVG. أدرج الصورة داخل SVG أولًا، أو ارفعها مع الملف."},{"question":"هل يمكنني استخدام خط ويب داخل SVG للتصدير إلى PNG؟","answer":"نعم، لكن الخط يجب أن يكون متاحًا في المتصفح أثناء التحويل. إذا لم يكن الخط متاحًا، فسيُستبدل بخط افتراضي."},{"question":"ما أكبر PNG يمكن أن ينتجه SVG؟","answer":"الحد الأقصى يعتمد على متصفحك وذاكرته، لكن معظم الأدوات تنتج PNG حتى 4000 بكسل أو أكثر. المقاييس الضخمة قد تفشل في المتصفحات الضعيفة."},{"question":"هل ملف PNG الناتج دون فقدان؟","answer":"نعم، PNG الناتج دون فقدان: البكسلات تُحفظ بدقة كاملة. التنقيط نفسه لا يفقد جودة، لكن المقياس الخاطئ قد يجعل الصورة ضبابية."}];
